+// Copyright (c) The Bitcoin Core developers
+// Distributed under the MIT software license, see the accompanying
+// file COPYING or http://www.opensource.org/licenses/mit-license.php.
+
+#include <test/util/block_validity.h>
+
+#include <pow.h>
+#include <test/util/mining.h>
+#include <util/check.h>
+
+#include <boost/test/unit_test.hpp>
+
+CBlock ValidationBlockValidityTestingSetup::MakeBlock(node::BlockCreateOptions options)
+{
+    auto block_ptr = PrepareBlock(m_node, options);
+    Assert(block_ptr);
+    return *block_ptr;
+}
+
+void ValidationBlockValidityTestingSetup::ResetBlock(CBlock& block)
+{
+    block.fChecked = block.m_checked_merkle_root = block.m_checked_witness_commitment = false;
+}
+
+BlockValidationState ValidationBlockValidityTestingSetup::TestValidity(CBlock& block, bool check_pow, bool check_merkle)
+{
+    ResetBlock(block);
+    LOCK(cs_main);
+    return TestBlockValidity(m_chainstate, block, check_pow, check_merkle);
+}
+
+COutPoint ValidationBlockValidityTestingSetup::AddCoin(const CScript& script_pub_key, CAmount amount)
+{
+    // Max trials to find a unique random outpoint
+    const int max_trials{5};
+    for (int trial_idx = 0; trial_idx < max_trials; ++trial_idx) {
+        COutPoint outpoint{Txid::FromUint256(m_rng.rand256()), 0};
+        LOCK(cs_main);
+        if (m_chainstate.CoinsTip().AccessCoin(outpoint).IsSpent()) {
+            m_chainstate.CoinsTip().AddCoin(outpoint, Coin(CTxOut(amount, script_pub_key), 1, false), true);
+            return outpoint;
+        }
+    }
+    BOOST_REQUIRE_MESSAGE(false, "AddCoin: failed to find an unused outpoint");
+    return {};
+}
+
+void ValidationBlockValidityTestingSetup::SolveBlockPoW(CBlock& block)
+{
+    ResetBlock(block);
+    const uint32_t start_nonce{block.nNonce};
+    while (!CheckProofOfWork(block.GetHash(), block.nBits, m_params)) {
+        ++block.nNonce;
+        BOOST_REQUIRE_MESSAGE(block.nNonce != start_nonce, "SolvePoW: exhausted all nonces without finding valid PoW");
+    }
+}
+
+BlockValidationState ValidationBlockValidityTestingSetup::ConnectBlock(CBlock& block)
+{
+    ResetBlock(block);
+    LOCK(cs_main);
+    BlockValidationState state;
+    CBlockIndex* tip = m_chainstate.m_chain.Tip();
+    Assert(tip);
+    CBlockIndex index_dummy{block};
+    const uint256 block_hash{block.GetHash()};
+    index_dummy.pprev = tip;
+    index_dummy.nHeight = tip->nHeight + 1;
+    index_dummy.phashBlock = &block_hash;
+    CCoinsViewCache view_dummy{&m_chainstate.CoinsTip()};
+    m_chainstate.ConnectBlock(block, state, &index_dummy, view_dummy, /*fJustCheck=*/true);
+    return state;
+}
+
+BlockValidationState ValidationBlockValidityTestingSetup::ProcessNewBlock(CBlock& block, bool force_processing, bool min_pow_checked)
+{
+    ResetBlock(block);
+    bool new_block{false};
+    m_node.chainman->ProcessNewBlock(std::make_shared<const CBlock>(block), force_processing, min_pow_checked, &new_block);
+    m_node.validation_signals->SyncWithValidationInterfaceQueue();
+    Assert(m_subscriber.m_checked_block_states.size() == 1);
+    BlockValidationState state{m_subscriber.m_checked_block_states.front()};
+    m_subscriber.ClearCheckedBlockStates();
+    return state;
+}
diff --git a/src/test/validation_block_header_tests.cpp b/src/test/validation_block_header_tests.cpp
new file mode 100644
index 0000000000..c5006e6bd0
--- /dev/null
+++ b/src/test/validation_block_header_tests.cpp
@@ -0,0 +1,142 @@
+// Copyright (c) The Bitcoin Core developers
+// Distributed under the MIT software license, see the accompanying
+// file COPYING or http://www.opensource.org/licenses/mit-license.php.
+
+#include <pow.h>
+#include <test/block_validity_checks.h>
+#include <test/util/block_validity.h>
+
+#include <boost/test/unit_test.hpp>
+
+/*
+ * Tests for block header validation rules, including Proof of Work (PoW),
+ * target difficulty (nBits), timestamps, and version bits.
+ */
+BOOST_FIXTURE_TEST_SUITE(validation_block_header_tests, ValidationBlockValidityTestingSetup)
+
+BOOST_AUTO_TEST_CASE(tbv_valid_block)
+{
+    // A standard block generated by the miner should pass all validity checks
+    // and, once submitted via ProcessNewBlock with valid PoW, advance the chain tip.
+    CBlock block = MakeBlock();
+    const int current_height = WITH_LOCK(cs_main, return m_chainstate.m_chain.Height());
+    CheckBlockValid(TestValidity(block));
+    CheckBlockValid(ConnectBlock(block));
+    BOOST_CHECK_MESSAGE(WITH_LOCK(cs_main, return m_chainstate.m_chain.Height()) == current_height, "Chain tip advanced unexpectedly");
+    SolveBlockPoW(block);
+    CheckBlockValid(ProcessNewBlock(block));
+    BOOST_CHECK_EQUAL(WITH_LOCK(cs_main, return m_chainstate.m_chain.Height()), current_height + 1);
+}
+
+BOOST_AUTO_TEST_CASE(tbv_wrong_prev)
+{
+    // Blocks must build on the current tip. Setting hashPrevBlock to an arbitrary value orphans the block.
+    // TestValidity detects this early ("inconclusive"); ProcessNewBlock rejects it as a missing prev block.
+    CBlock block = MakeBlock();
+    block.hashPrevBlock = uint256::ONE;
+    const auto reason = "inconclusive-not-best-prevblk";
+    CheckBlockInvalid(TestValidity(block), BlockValidationResult::BLOCK_RESULT_UNSET, reason, "");
+    // ConnectBlock builds on the current tip via a dummy index regardless of the block's hashPrevBlock field.
+    CheckBlockValid(ConnectBlock(block));
+    SolveBlockPoW(block);
+    CheckBlockInvalid(ProcessNewBlock(block), BlockValidationResult::BLOCK_MISSING_PREV, "prev-blk-not-found", "");
+}
+
+BOOST_AUTO_TEST_CASE(tbv_high_hash)
+{
+    // The block hash must be below the difficulty target. We increment the nonce until the hash is above the target.
+    CBlock block = MakeBlock();
+    const uint32_t max_nonce_trials{100};
+    block.nNonce = 0;
+    while (CheckProofOfWork(block.GetHash(), block.nBits, m_params)) {
+        ++block.nNonce;
+        BOOST_REQUIRE_MESSAGE(block.nNonce < max_nonce_trials, "Failed to find a high-hash nonce within 100 iterations");
+    }
+    const auto reason = "high-hash";
+    const auto debug = "proof of work failed";
+    CheckBlockInvalid(TestValidity(block, true), BlockValidationResult::BLOCK_INVALID_HEADER, reason, debug);
+    // ConnectBlock calls CheckBlock with fCheckPOW=false, so PoW is not verified.
+    CheckBlockValid(ConnectBlock(block));
+    CheckBlockInvalid(ProcessNewBlock(block), BlockValidationResult::BLOCK_INVALID_HEADER, reason, debug);
+}
+
+BOOST_AUTO_TEST_CASE(tbv_bad_diffbits)
+{
+    // The nBits field must match the target difficulty required by the network at the current height.
+    CBlock block = MakeBlock();
+    const unsigned int pow_limit = UintToArith256(m_params.powLimit).GetCompact();
+    BOOST_CHECK_EQUAL(block.nBits, pow_limit);
+    block.nBits = pow_limit - 1;
+    const auto reason = "bad-diffbits";
+    const auto debug = "incorrect proof of work";
+    CheckBlockInvalid(TestValidity(block), BlockValidationResult::BLOCK_INVALID_HEADER, reason, debug);
+    // ConnectBlock does not call ContextualCheckBlockHeader, so nBits is not validated.
+    CheckBlockValid(ConnectBlock(block));
+    SolveBlockPoW(block);
+    CheckBlockInvalid(ProcessNewBlock(block), BlockValidationResult::BLOCK_INVALID_HEADER, reason, debug);
+}
+
+BOOST_AUTO_TEST_CASE(tbv_time_too_old)
+{
+    // Block time must be strictly greater than the median of the previous 11 blocks.
+    CBlock block = MakeBlock();
+    block.nTime = WITH_LOCK(cs_main, return m_chainstate.m_chain.Tip()->GetMedianTimePast());
+    const auto reason = "time-too-old";
+    const auto debug = "block's timestamp is too early";
+    CheckBlockInvalid(TestValidity(block), BlockValidationResult::BLOCK_INVALID_HEADER, reason, debug);
+    // ConnectBlock does not call ContextualCheckBlockHeader, so the timestamp is not validated.
+    CheckBlockValid(ConnectBlock(block));
+    SolveBlockPoW(block);
+    CheckBlockInvalid(ProcessNewBlock(block), BlockValidationResult::BLOCK_INVALID_HEADER, reason, debug);
+}
+
+BOOST_AUTO_TEST_CASE(tbv_time_too_new)
+{
+    // Block time must not be more than 2 hours in the future according to the node's adjusted time.
+    CBlock block = MakeBlock();
+    block.nTime = TicksSinceEpoch<std::chrono::seconds>(NodeClock::now()) + MAX_FUTURE_BLOCK_TIME + 1;
+    const auto reason = "time-too-new";
+    const auto debug = "block timestamp too far in the future";
+    CheckBlockInvalid(TestValidity(block), BlockValidationResult::BLOCK_TIME_FUTURE, reason, debug);
+    // ConnectBlock does not call ContextualCheckBlockHeader, so the timestamp is not validated.
+    CheckBlockValid(ConnectBlock(block));
+    SolveBlockPoW(block);
+    CheckBlockInvalid(ProcessNewBlock(block), BlockValidationResult::BLOCK_TIME_FUTURE, reason, debug);
+}
+
+BOOST_AUTO_TEST_CASE(tbv_bad_version)
+{
+    // Outdated block versions are rejected once the network has upgraded to higher version.
+    CBlock block = MakeBlock();
+    block.nVersion = VERSIONBITS_LAST_OLD_BLOCK_VERSION - 1;
+    const auto reason = strprintf("bad-version(0x%08x)", block.nVersion);
+    const auto debug = strprintf("rejected nVersion=0x%08x block", block.nVersion);
+    CheckBlockInvalid(TestValidity(block), BlockValidationResult::BLOCK_INVALID_HEADER, reason, debug);
+    // ConnectBlock does not call ContextualCheckBlockHeader, so the block version is not validated.
+    CheckBlockValid(ConnectBlock(block));
+    SolveBlockPoW(block);
+    CheckBlockInvalid(ProcessNewBlock(block), BlockValidationResult::BLOCK_INVALID_HEADER, reason, debug);
+}
+
+BOOST_AUTO_TEST_CASE(tbv_bad_prevblk)
+{
+    // TestValidity cannot distinguish building on an invalidated block from a genuine orphan:
+    // after InvalidateBlock, the chain rolls back and hashPrevBlock no longer equals the active
+    // tip, so TestValidity returns "inconclusive-not-best-prevblk" — the same result as
+    // tbv_wrong_prev. Only ProcessNewBlock, which consults the block index, can return the more
+    // specific BLOCK_INVALID_PREV / "bad-prevblk".
+    CBlockIndex* tip = WITH_LOCK(cs_main, return m_chainstate.m_chain.Tip());
+    Assert(tip);
+    const uint256 invalidated_hash = tip->GetBlockHash();
+    BlockValidationState invalid_state;
+    BOOST_REQUIRE(m_chainstate.InvalidateBlock(invalid_state, tip));
+    CBlock block = MakeBlock();
+    block.hashPrevBlock = invalidated_hash;
+    CheckBlockInvalid(TestValidity(block), BlockValidationResult::BLOCK_RESULT_UNSET, "inconclusive-not-best-prevblk", "");
+    // ConnectBlock does not consult the block index, so it does not detect an invalid prev block.
+    CheckBlockValid(ConnectBlock(block));
+    SolveBlockPoW(block);
+    CheckBlockInvalid(ProcessNewBlock(block), BlockValidationResult::BLOCK_INVALID_PREV, "bad-prevblk", "");
+}
+
+BOOST_AUTO_TEST_SUITE_END()
